/* Keep the atlas palette, but use a compact operating layout: evidence first,
   details on demand, and no animation that suggests a model is live. */
:root {
  --ink: #192e40;
  --muted: #4e6477;
  --blue: #173e67;
  --deep: #102e4e;
  --paper: #eef3f7;
  --white: #ffffff;
  --line: #c5d2de;
  --pale: #dfeaf4;
  --amber: #a34b14;
  --amber-bg: #fff0e1;
  --green: #235c41;
  --green-bg: #edf5ef;
  --red: #9a292d;
  --red-bg: #fceff0;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  line-height: 1.5;
  color: var(--ink);
  background: var(--white);
  color-scheme: light;
}
* { box-sizing: border-box; }
body { margin: 0; }
::selection { background: var(--pale); color: var(--deep); }
:focus-visible { outline: 3px solid var(--amber); outline-offset: 3px; }
a { color: var(--blue); text-underline-offset: 4px; }
button, input, select {
  min-height: 44px;
  border: 1px solid var(--line);
  border-radius: 6px;
  font: inherit;
  font-size: .875rem;
  color: var(--ink);
  background: var(--white);
}
button { padding: 9px 14px; cursor: pointer; font-weight: 600; }
button:hover { background: var(--paper); border-color: var(--blue); }
button:active { background: var(--pale); }
button:disabled { color: var(--muted); border-color: var(--line); background: var(--paper); opacity: .6; cursor: default; }
input, select { padding: 9px 12px; max-width: 100%; caret-color: var(--blue); }
input:hover, select:hover { border-color: var(--muted); }
input::placeholder { color: var(--muted); }
input[type=search] { width: 100%; }
label { display: block; margin-bottom: 6px; font-size: .75rem; font-weight: 600; }
code, pre { font-family: ui-monospace, SFMono-Regular, Consolas, monospace; }
p { max-width: 74ch; margin: 0 0 12px; }
h1, h2, h3 { color: var(--deep); text-wrap: balance; }
h1 { margin: 0 0 8px; font: 500 2.25rem/1.15 Charter, Georgia, serif; letter-spacing: -.025em; }
h2 { margin: 0; font-size: 1.0625rem; font-weight: 650; line-height: 1.4; }
h3 { margin: 0 0 10px; font-size: .9375rem; line-height: 1.4; }
pre { overflow: auto; max-height: 420px; padding: 16px; border-radius: 6px; white-space: pre-wrap; overflow-wrap: anywhere; background: var(--paper); font-size: .8125rem; line-height: 1.6; }
details { margin: 10px 0; }
summary { padding: 8px 0; cursor: pointer; overflow-wrap: anywhere; color: var(--blue); }
