'use strict';
const $=id=>document.getElementById(id);
const el=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;};
const state={token:'',config:null,dirty:false,offset:0,more:false,review:null,detailGeneration:0,timer:null};
const json=value=>JSON.stringify(value,null,2);
const stamp=value=>value?new Date(value).toLocaleString():'Not observed';
function notice(text){$('notice').textContent=text;}
async function api(path,body){
 const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),path.endsWith('/activate')?180000:20000);
 try{
  const response=await fetch(path,{method:body===undefined?'GET':'POST',cache:'no-store',signal:controller.signal,headers:{Authorization:`Bearer ${state.token}`,...(body===undefined?{}:{'Content-Type':'application/json','X-Mrmr-Control':'1'})},body:body===undefined?undefined:JSON.stringify(body)});
  if(response.status===401){lock();throw Error('Operator token rejected. Unlock again.');}
  if(!response.ok)throw Error((await response.text()).slice(0,1000));
  return response.json();
 }finally{clearTimeout(timer);}
}
function action(id,fn){$(id).addEventListener('click',async e=>{e.preventDefault();const b=e.currentTarget;b.disabled=true;try{await fn();}catch(err){notice(err.name==='AbortError'?'Request timed out. Refresh runtime state before retrying a change.':err.message);}finally{b.disabled=false;}});}
function lock(){state.token='';state.detailGeneration++;clearTimeout(state.timer);$('app').hidden=true;$('login').hidden=false;$('logout').hidden=true;$('token').value='';$('yaml').value='';state.config=null;state.dirty=false;for(const id of ['events','event-detail','review-evidence','review-history','audit','evaluations','revisions','diff-content','configured-sources','source-health','model-health','overview-content'])$(id).replaceChildren();notice('Management locked.');}
function page(){const name=location.hash.slice(1)||'overview';for(const section of document.querySelectorAll('[data-page]'))section.hidden=section.dataset.page!==name;for(const a of document.querySelectorAll('nav a')){if(a.hash===`#${name}`)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');}document.title=`mrmr · ${name}`;}
window.addEventListener('hashchange',page);page();
$('login-form').addEventListener('submit',async e=>{e.preventDefault();state.token=REDACTED;$('token').value='';try{await loadConfig();$('login').hidden=true;$('app').hidden=false;$('logout').hidden=false;await overview();await events();const id=new URLSearchParams(location.search).get('event');if(id)await detail(id);notice('Operator access active. Changes are recorded.');}catch(err){notice(err.message);}});
$('logout').addEventListener('click',lock);
function record(title,text){const n=el('div');n.className='record';n.append(el('h3',title),el('p',text));return n;}
async function overview(){
 clearTimeout(state.timer);if(!state.token)return;
 try{
  if(!state.config||state.config.setup){$('overview-content').replaceChildren(record('Setup required','Open Configure to set a model endpoint and source. Collection is disabled.'));return;}
  const data=await api('/dashboard/api/overview');$('host').textContent=data.hostname;
  $('freshness').textContent=`Runtime answered ${stamp(data.at)}. Source evidence resets when its runtime revision changes.`;
  const s=data.summary;$('overview-content').replaceChildren(record('Stored evidence',`${s.events} events · ${s.unlabeled} unlabeled · ${s.pending} unfinished execution intents`));
  const effects=data.policy.filter(r=>r.outcome!=='ignore'),live=effects.filter(r=>!r.shadow).length;
  $('overview-content').append(record('Effect boundary',state.config.shadow_override?'Operator safety gate: effects blocked.':live?`${live} configured live effect rule(s).`:'Configured effects are shadowed or ignored.'));
  const links=el('p');for(const [label,view] of [['Inspect errors','errors'],['Review unlabeled events','unlabeled'],['Inspect unfinished intents','pending']]){const a=el('a',label);a.href=`?view=${view}#activity`;a.addEventListener('click',e=>{if(e.ctrlKey||e.metaKey||e.shiftKey)return;e.preventDefault();$('view').value=view;$('query').value='';state.offset=0;location.hash='activity';saveSearch();events().catch(e=>notice(e.message));});links.append(a,document.createTextNode(' · '));}$('overview-content').append(links);
  $('source-health').replaceChildren();for(const source of data.sources){const h=source.health,finished=new Date(h.finished_at),limit=Math.max(30000,source.every_ms*3);const status=source.paused?'Paused; cursor retained':h.failed?'Last poll failed':h.running?'Poll in progress':finished.getFullYear()>1?(new Date(data.at)-finished>limit?'No recent completed poll':'Last poll completed; an empty poll is not a failure'):'First poll not observed';$('source-health').append(record(source.name,`${status}. ${source.type}; ${source.every_ms/1000}s interval.`));}if(!data.sources.length)$('source-health').append(el('p','No pull sources configured. HTTP ingress remains available.'));
  $('model-health').replaceChildren();for(const m of s.models)$('model-health').append(record(m.interpreter,`${m.model} · ${m.successes}/${m.count} successful · median ${m.median_ms??'not measured'} ms · ${m.errors} errors. Latest decision ${stamp(m.last_at)}.`));
 }catch(err){$('freshness').textContent='Status refresh failed. Displayed evidence may be stale.';notice(err.message);}
 finally{if(state.token&&!document.hidden)state.timer=setTimeout(overview,10000);}
}
action('refresh-overview',overview);document.addEventListener('visibilitychange',()=>{clearTimeout(state.timer);if(!document.hidden&&state.token)overview();else $('freshness').textContent='Refresh paused while this page is hidden; displayed evidence may be stale.';});
function saveSearch(){const p=new URLSearchParams();if($('query').value.trim())p.set('q',$('query').value.trim());if($('view').value!=='all')p.set('view',$('view').value);if(state.offset)p.set('offset',state.offset);history.pushState(null,'',`${location.pathname}?${p}#activity`);}
function restoreSearch(){const p=new URLSearchParams(location.search);$('query').value=(p.get('q')||'').slice(0,200);$('view').value=['all','errors','pending','unlabeled','shadow','ignore'].includes(p.get('view'))?p.get('view'):'all';state.offset=Math.max(0,Math.min(100000,Number(p.get('offset'))||0));}
restoreSearch();
async function events(){if(!state.token||state.config?.setup)return;const params=new URLSearchParams({q:$('query').value.trim(),view:$('view').value,offset:state.offset});const data=await api(`/dashboard/api/events?${params}`);$('events').replaceChildren();state.more=data.more;for(const e of data.events){const n=record(e.subject||e.type,`${e.source} · ${e.type} · ${stamp(e.ingested_at)} · ${e.outcome||'No execution recorded'} / ${e.execution_status||'unknown'}`);const a=el('a','Inspect event');const p=new URLSearchParams(location.search);p.set('event',e.id);a.href=`?${p}#activity`;a.addEventListener('click',evt=>{if(evt.ctrlKey||evt.metaKey||evt.shiftKey)return;evt.preventDefault();history.pushState(null,'',a.href);detail(e.id).catch(e=>notice(e.message));});n.append(el('p',e.message),a);$('events').append(n);}if(!data.events.length)$('events').append(el('p','No matching events. Check source scope and poll evidence.'));$('previous').disabled=state.offset===0;$('next').disabled=!data.more||state.offset>=100000;$('page-info').textContent=data.events.length?`${state.offset+1}–${state.offset+data.events.length}`:'No results';}
$('search').addEventListener('submit',e=>{e.preventDefault();state.offset=0;saveSearch();events().catch(e=>notice(e.message));});action('previous',async()=>{state.offset=Math.max(0,state.offset-50);saveSearch();await events();});action('next',async()=>{state.offset=Math.min(100000,state.offset+50);saveSearch();await events();});
async function detail(id){const generation=++state.detailGeneration;const data=await api(`/dashboard/api/event?id=${encodeURIComponent(id)}`);if(generation!==state.detailGeneration||!state.token)return;const root=$('event-detail');root.hidden=false;root.replaceChildren(el('h2',`Event ${id}`));for(const x of data.executions||[])root.append(el('p',x.status==='pending'?'Unfinished intent: the effect may or may not have occurred.':`${x.outcome} · ${x.status}${x.status==='shadow'?' · no effect performed':''}`));const review=el('button','Review this event');review.addEventListener('click',()=>{$('review-id').value=id;location.hash='review';loadReview().catch(e=>notice(e.message));});root.append(review);const parent=data.event.provenance?.parent_event_id;for(const related of [parent,...(data.child_event_ids||[])].filter(Boolean)){const p=el('p'),a=el('a',`${related===parent?'Parent':'Child'}: ${related}`);const params=new URLSearchParams(location.search);params.set('event',related);a.href=`?${params}#activity`;a.addEventListener('click',e=>{if(e.ctrlKey||e.metaKey||e.shiftKey)return;e.preventDefault();history.pushState(null,'',a.href);detail(related).catch(e=>notice(e.message));});p.append(a);root.append(p);}root.append(el('h3','Normalized Event'),el('pre',data.event_json),el('h3','Decisions and executions'),el('pre',json({decisions:data.decisions,executions:data.executions})),el('h3','Trace'),el('pre',json(data.trace||[])));root.focus();root.scrollIntoView({block:'start'});}
window.addEventListener('popstate',()=>{restoreSearch();page();if(state.token){events().catch(e=>notice(e.message));const id=new URLSearchParams(location.search).get('event');if(id)detail(id).catch(e=>notice(e.message));else{$('event-detail').hidden=true;state.detailGeneration++;}}});
async function loadReview(){const id=$('review-id').value.trim();const [review,evidence]=await Promise.all([api(`/manage/api/review?id=${encodeURIComponent(id)}`),api(`/dashboard/api/event?id=${encodeURIComponent(id)}`)]);state.review={id,...review};$('review-evidence').replaceChildren(el('h2',evidence.event.subject||evidence.event.type),el('pre',evidence.event_json));$('review-history').textContent=json({decisions:evidence.decisions,current_label:review.label,history:review.history});$('review-state').value=review.state==='unreviewed'?'reviewed':review.state;$('review-origin').value=review.origin;$('category').value='';$('requires-action').value='';$('expected-outcome').value='';$('review-form').hidden=false;}
